from pathlib import Path
p=Path('agent_notes/lbc_other_events.md'); s=p.read_text(encoding='utf8')
edits={
'### `lbc:other/event/halloween/start`':'Ставит глобальное событие в progression всем игрокам через grant advancement и проигрывает общий Halloween sound. Функция не запускает все эффекты предметов сама: пищевые и боевые механики имеют отдельные hooks. [Исходник](../world/datapacksdisabled/LBC/data/lbc/function/other/event/halloween/start.mcfunction)',
'### `lbc:other/event/halloween/eat_halloween_food`':'Когда advancement reward передаёт сюда съеденную Halloween-еду, функция увеличивает `pumpkin_counter` на 1 и по каждому точному значению 1..100 делает `return run advancement grant` с соответствующим variant-ID. Эти команды сами по себе не проверяют предмет или тип еды; критерий потребления задан вызывающим advancement. [Исходник](../world/datapacksdisabled/LBC/data/lbc/function/other/event/halloween/eat_halloween_food.mcfunction)',
'### `lbc:other/event/halloween/player_tick_1s`':'Раз в секунду добавляет игроку случайное целое 1..50 к `swrg.memcoins` (сначала инициализирует отсутствующий score нулём), показывает количество через tellraw и выбирает scare-сцену. Случайное значение ограничено 1..7, хотя literal switch содержит также ветку 8; следовательно, восьмая не вызывается этим выбором. [Исходник](../world/datapacksdisabled/LBC/data/lbc/function/other/event/halloween/player_tick_1s.mcfunction)',
'### `lbc:other/event/halloween/screamer_activate`':'Выбирает случайное целое 1..7 и через `return run` вызывает ровно соответствующую из сцен 1–7; записанные ниже ветки 8 и выше недостижимы, потому что их значения не может вернуть random. [Исходник](../world/datapacksdisabled/LBC/data/lbc/function/other/event/halloween/screamer_activate.mcfunction)',
'### `lbc:other/event/halloween/jack_o_lantern_spawn`':'Создаёт block_display-фонарь с тегами `slowraycast`, `rare`, `jack_o_lantern`, `shield_blockable`, копирует ему rotation, `lbcID2` и `team_number` источника. Затем ищет игрока с тем же ID и временно помечает его `damager`, чтобы последующее попадание могло быть атрибутировано владельцу. Это только spawn/setup этап луча. [Исходник](../world/datapacksdisabled/LBC/data/lbc/function/other/event/halloween/jack_o_lantern_spawn.mcfunction)',
'### `lbc:other/event/halloween/jack_o_lantern_tick`':'В каждом тике передвигает луч по его собственной позиции, рисует soul_fire_flame и проверяет столкновения. Selector с `dx=dy=dz=0` ищет незатегованную цель-моба в кубе 1×1×1 на позиции исполнения; если её находит, запускает explode. Если траектория попадает в блок вне `#minecraft:airs`, также взрывается; иначе движется до Distance 8 (выход через homing helper), но рекурсивный шаг на 0,2 блока задан только для Distance 1..7. [Исходник](../world/datapacksdisabled/LBC/data/lbc/function/other/event/halloween/jack_o_lantern_tick.mcfunction)',
'### `lbc:other/event/halloween/jack_o_lantern_check`':'Помечает ближайшего подходящего игрока `damager`, если его `lbcID2` совпадает с владельцем луча, затем проверяет cube-selector на незатегованного моба. При цели вызывает взрывную ветку; в любом случае снимает `damager` и удаляет ближайший screamer display с соответствующим тегом в радиусе 2. [Исходник](../world/datapacksdisabled/LBC/data/lbc/function/other/event/halloween/jack_o_lantern_check.mcfunction)',
'### `lbc:other/event/halloween/jack_o_lantern_explode`':'Создаёт короткоживущую ракету-фейерверк и записывает ей Owner найденного `damager`, если он есть. Затем наносит всем mob-tag entities в радиусе 3,5 урон 6 типа arrow (с Owner-атрибуцией при найденном игроке), очищает временные теги и убивает источник луча. [Исходник](../world/datapacksdisabled/LBC/data/lbc/function/other/event/halloween/jack_o_lantern_explode.mcfunction)'
}
for h,t in edits.items():
 if h not in s: print('MISSING',h); continue
 a=s.index(h)+len(h); b=s.find('\n### ',a); b=b if b>=0 else s.find('\n## ',a); b=b if b>=0 else len(s); s=s[:a]+'\n\n'+t+s[b:]
p.write_text(s,encoding='utf8')
